/**
 * Seed & Variety Explorer types (Build 6, 2026-11-06).
 * Data: OpenPlantDB (CC0 1.0), generated by
 * scripts/build-varieties-data.mjs into src/data/varieties/.
 */

export interface RangeF {
  min: number;
  max: number;
}

/** Slim record — explorer cards, search, API list responses. */
export interface VarietyIndexEntry {
  slug: string;
  name: string;
  cropGroup: string;
  dtmMin: number;
  dtmMax: number;
  /** "seed" | "transplant" — what the DTM counts from. */
  maturityFrom: string;
  /** Catalog resistance code strings (e.g. V, FF, N), when the source states them. */
  resistanceCodes: string[];
  /** Named diseases the source describes the variety as resistant/tolerant to. */
  resistances: string[];
}

/** Full record — variety detail pages and API get responses. */
export interface Variety extends VarietyIndexEntry {
  cultivar: string;
  scientificName: string;
  subcategory: string;
  germinationDays: RangeF | null;
  germinationSoilTempF: RangeF | null;
  zones: RangeF | null;
  spacingIn: RangeF | null;
  heightIn: RangeF | null;
  spreadIn: RangeF | null;
  sun: string | null;
  water: string | null;
  frostTolerance: string | null;
  season: string | null;
  sowMethod: string | null;
  plantingNote: string | null;
  directions: string | null;
  /** Provenance citations from the source dataset — NOT vendor buy links. */
  sources: string[];
}
